window.receiveProjectSource({"path": "test/integration/web_extraction/test_l3_retry_idempotency.py", "lines": ["\"\"\"Integration tests for L3 (manual upload) retry idempotency.", "", "Companion to ``test_l2_retry_idempotency.py``. Covers:", "", "- ``find_existing_l3_outcome`` returns the ``ActivityArticleStatus`` row written", "  by a prior L3 attempt, or ``None`` if no prior attempt left one.", "- ``manual_upload_pipeline`` short-circuits when the prior attempt finished as", "  a duplicate (``ActivityArticleStatus.duplicated_article_id`` set) \u2014 neither", "  embedding nor dedup runs again.", "", "The self-match prevention path (``exclude_article_id`` plumbed into", "``deduplicate_article``) is exercised by the unit tests in", "``test/unit/microservices/web_extraction/test_deduplication.py``.", "\"\"\"", "", "from typing import Any", "from unittest.mock import AsyncMock, Mock", "from uuid import UUID, uuid4", "", "import pytest", "from accelerate_models.documents.app.models import Document", "from accelerate_models.documents.app.models.doc_images import DocImage", "from accelerate_models.documents.app.models.enum import DocumentStatus, ImageType", "from accelerate_models.documents.app.models.source_data import SourceData", "from sqlalchemy import select, text", "", "import common.models.all as Tables", "from common.constants.source_data_models import (", "    LOC_DATA_MODEL_ID,", "    ORG_DATA_MODEL_ID,", "    PEOPLE_DATA_MODEL_ID,", ")", "from common.models.enums import ArticleType, RunState, ServiceLayer", "from common.services.api_helper import APIHelper", "from common.utils.well_known_data import REQUEST_TYPES", "from db.session_manager_async import sessionmanager_accelerate, sessionmanager_datalake", "from microservices.web_extraction.aws.sqs.web_extraction_client import WebExtractionClient", "from microservices.web_extraction.config import test_config as web_test_config", "from microservices.web_extraction.models.enums import ArticleImageRole, ArticleImageStatus", "from microservices.web_extraction.schemas.embedding import ChunkEmbedding, ChunkVectors", "from microservices.web_extraction.services import web_extraction as webex_module", "from microservices.web_extraction.services.helpers.article_classification import (", "    ArticleClassification,", ")", "from microservices.web_extraction.services.helpers.layer_two import (", "    DeduplicationClassification,", "    DeduplicationResult,", ")", "from microservices.web_extraction.services.helpers.manual_upload import (", "    find_existing_l3_outcome,", "    find_l3_prior_article_id,", "    write_manual_upload_for_new_article,", ")", "from microservices.web_extraction.services.web_extraction import WebExtractionService", "from test.integration._shared import queue_urls", "from test.integration._shared.db import _get_real_doc_id, get_test_feeds", "from test.integration._shared.preseeding import (", "    ensure_request_types,", "    preseed_article,", "    preseed_feeds_sent_messages,", "    preseed_manual_upload,", "    preseed_webex_l1_activities,", "    preseed_webex_l2_activities,", "    preseed_webex_l3_activities,", ")", "", "from ._image_helpers import create_accelerate_document, seed_image_rows", "from .pretest import ensure_manual_upload_feed", "", "pytestmark = pytest.mark.integration", "", "", "def _build_webex_client_for_l3() -> WebExtractionClient:", "    \"\"\"Build a minimal WebExtractionClient for invoking ``manual_upload_pipeline``.\"\"\"", "    return WebExtractionClient(", "        source_queue_url=queue_urls.webex_source_queue_url(),", "        target_queue_map={", "            (", "                REQUEST_TYPES.AI_QUESTIONNAIRE_SVC,", "                ServiceLayer.LAYER_ONE,", "            ): queue_urls.webex_ai_questionnaire_target_queue_url(),", "        },", "        tracking_table=Tables.WebExtractionSentSQSMessage,", "    )", "", "", "async def _run_manual_upload_pipeline(", "    *, l3_activity_id: UUID, account_id: int, doc_id: int, s3_key: str", ") -> None:", "    \"\"\"Drive ``manual_upload_pipeline`` once with the suite's standard wiring.", "", "    The single place this suite constructs an ``APIHelper``, opens the datalake /", "    accelerate session pair, and builds a ``WebExtractionService`` around them.", "    Callers install whatever stubs their scenario needs before delegating here, so", "    a change to the service constructor or the pipeline signature lands in one", "    place rather than once per scenario.", "", "    :param l3_activity_id: L3 activity the pipeline runs for.", "    :type l3_activity_id: UUID", "    :param account_id: Account performing the upload.", "    :type account_id: int", "    :param doc_id: Accelerate document id the pipeline is driven with.", "    :type doc_id: int", "    :param s3_key: S3 key recorded on the upload rows.", "    :type s3_key: str", "    :return: None", "    :rtype: None", "    \"\"\"", "    api_helper = APIHelper()", "    try:", "        async with (", "            sessionmanager_datalake.session() as datalake_session,", "            sessionmanager_accelerate.session() as accelerate_session,", "        ):", "            service = WebExtractionService(", "                datalake_db_session=datalake_session,", "                web_extraction_client=_build_webex_client_for_l3(),", "                accelerate_db_session=accelerate_session,", "                api_helper=api_helper,", "            )", "            await service.manual_upload_pipeline(", "                activity_id=l3_activity_id,", "                account_id=account_id,", "                doc_id=doc_id,", "                s3_bucket=\"test-bucket\",", "                s3_key=s3_key,", "            )", "    finally:", "        await api_helper.session.close()", "", "", "async def _seed_l3_activity_with_canonical_article() -> tuple[UUID, UUID]:", "    \"\"\"Preseed an L3 activity + an Article + an ActivityArticleStatus pointing to that", "    article (as the canonical write of a prior L3 attempt). Return ``(l3_activity_id, article_id)``.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        await ensure_manual_upload_feed(session)", "        _, article_ids = await preseed_article(db=session, num_articles=1)", "        article_id = article_ids[0]", "        _, l3_activity_ids = await preseed_webex_l3_activities(db=session, num_activities=1)", "        l3_activity_id = l3_activity_ids[0]", "        session.add(", "            Tables.ActivityArticleStatus(", "                article_id=article_id,", "                layer_three_activity_id=l3_activity_id,", "                layer=ServiceLayer.LAYER_THREE,", "            )", "        )", "        await session.commit()", "    return l3_activity_id, article_id", "", "", "async def _seed_l3_activity_with_existing_duplicate(", "    *, account_id: int, doc_id: int", ") -> tuple[UUID, UUID, UUID]:", "    \"\"\"Preseed the full chain a prior L3 attempt would have written when it", "    classified as DUPLICATE: Article \u2192 ManualUpload \u2192 ManualUploadAccount \u2192", "    DuplicatedArticle \u2192 ActivityArticleStatus(layer_three_activity_id, duplicated_article_id).", "", "    Returns ``(l3_activity_id, duplicated_article_id, article_id)``.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        await ensure_manual_upload_feed(session)", "        _, article_ids = await preseed_article(db=session, num_articles=1)", "        article_id = article_ids[0]", "        _, manual_upload_ids = await preseed_manual_upload(db=session, article_ids=[article_id])", "        manual_upload_id = manual_upload_ids[0]", "        _, l3_activity_ids = await preseed_webex_l3_activities(db=session, num_activities=1)", "        l3_activity_id = l3_activity_ids[0]", "", "        manual_upload_account = Tables.ManualUploadAccount(", "            manual_upload_id=manual_upload_id,", "            layer_three_activity_id=l3_activity_id,", "            account_id=account_id,", "            doc_id=doc_id,", "            s3_bucket=\"test-bucket\",", "            s3_key=f\"manual_uploads/l3_retry_{l3_activity_id}.pdf\",", "        )", "        session.add(manual_upload_account)", "        await session.flush()", "", "        duplicated_article = Tables.DuplicatedArticle(", "            matched_article_id=article_id,", "            article_type=ArticleType.MANUAL_UPLOAD,", "            similarity_score=0.99,", "            chunk_match_info={\"matched_chunk_index\": 0, \"incoming_chunk_index\": 0},", "            content=\"prior-attempt content\",", "            manual_upload_account_id=manual_upload_account.id,", "        )", "        session.add(duplicated_article)", "        await session.flush()", "", "        session.add(", "            Tables.ActivityArticleStatus(", "                duplicated_article_id=duplicated_article.id,", "                layer_three_activity_id=l3_activity_id,", "                layer=ServiceLayer.LAYER_THREE,", "            )", "        )", "        await session.commit()", "        return l3_activity_id, duplicated_article.id, article_id", "", "", "@pytest.mark.asyncio", "async def test_find_existing_l3_outcome_returns_canonical_article_row():", "    \"\"\"Helper returns the ActivityArticleStatus when a prior attempt wrote a canonical Article.\"\"\"", "    l3_activity_id, article_id = await _seed_l3_activity_with_canonical_article()", "", "    async with sessionmanager_datalake.session() as session:", "        result = await find_existing_l3_outcome(session, l3_activity_id)", "", "    assert result is not None", "    assert result.layer_three_activity_id == l3_activity_id", "    assert result.article_id == article_id", "    assert result.duplicated_article_id is None", "", "", "@pytest.mark.asyncio", "async def test_find_existing_l3_outcome_returns_none_when_no_prior_attempt():", "    \"\"\"Helper returns None when no ActivityArticleStatus exists for the activity.\"\"\"", "    async with sessionmanager_datalake.session() as session:", "        result = await find_existing_l3_outcome(session, uuid4())", "    assert result is None", "", "", "@pytest.mark.asyncio", "async def test_l3_retry_short_circuits_when_prior_attempt_finished_as_duplicate(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"If a prior L3 attempt wrote a DuplicatedArticle, retry must short-circuit before", "    embedding and finalize as RunState.DUPLICATE. The accelerate document is re-asserted", "    to DUPLICATE (idempotent UPDATE).\"\"\"", "    real_doc_id = await _get_real_doc_id()", "    account_id = 39_999", "    l3_activity_id, duplicated_article_id, _ = await _seed_l3_activity_with_existing_duplicate(", "        account_id=account_id,", "        doc_id=real_doc_id,", "    )", "", "    # If the short-circuit ever regresses, the pipeline would call embed_article_chunks", "    # next \u2014 wiring the call to raise here turns that regression into a test failure.", "    from microservices.web_extraction.services import web_extraction as webex_module", "", "    def _embed_should_not_be_called(*_args, **_kwargs):", "        raise AssertionError(\"embed_article_chunks called despite short-circuit on DUPLICATE\")", "", "    monkeypatch.setattr(webex_module, \"embed_article_chunks\", _embed_should_not_be_called)", "    monkeypatch.setattr(web_test_config, \"DEBUG\", True)", "", "    await _run_manual_upload_pipeline(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=real_doc_id,", "        s3_key=f\"manual_uploads/l3_retry_{l3_activity_id}.pdf\",", "    )", "", "    # Verify L3 activity ended as DUPLICATE.", "    async with sessionmanager_datalake.session() as session:", "        activity = await session.get(Tables.WebExtractionLayerThreeActivity, l3_activity_id)", "        assert activity is not None", "        assert activity.run_state == RunState.DUPLICATE", "", "        # The pre-existing duplicated_article row must still be the only one for this activity.", "        rows = (", "            await session.execute(", "                Tables.ActivityArticleStatus.__table__.select().where(", "                    Tables.ActivityArticleStatus.layer_three_activity_id == l3_activity_id", "                )", "            )", "        ).fetchall()", "        assert len(rows) == 1", "        assert rows[0].duplicated_article_id == duplicated_article_id", "", "", "@pytest.mark.asyncio", "async def test_multi_anchor_activity_recovery_scoped_to_current_attempt():", "    \"\"\"Both anchor lookups scope by the attempt's (account_id, doc_id) keys.", "", "    Nothing schema-level caps an activity at one ManualUploadAccount row, so an", "    activity with anchors for two accounts must neither make the single-row", "    reads ambiguous (``MultipleResultsFound``) nor recover another attempt's", "    article.", "    \"\"\"", "    account_a, doc_a = 71_001, 81_001", "    account_b, doc_b = 71_002, 81_002", "", "    async with sessionmanager_datalake.session() as session:", "        await ensure_manual_upload_feed(session)", "        _, article_ids = await preseed_article(db=session, num_articles=2)", "        _, manual_upload_ids = await preseed_manual_upload(db=session, article_ids=article_ids)", "        _, l3_activity_ids = await preseed_webex_l3_activities(db=session, num_activities=1)", "        l3_activity_id = l3_activity_ids[0]", "", "        mua_ids: list[UUID] = []", "        anchors = [(account_a, doc_a), (account_b, doc_b)]", "        for manual_upload_id, (acct, doc) in zip(manual_upload_ids, anchors, strict=True):", "            mua = Tables.ManualUploadAccount(", "                manual_upload_id=manual_upload_id,", "                layer_three_activity_id=l3_activity_id,", "                account_id=acct,", "                doc_id=doc,", "                s3_bucket=\"test-bucket\",", "                s3_key=f\"manual_uploads/multi_anchor_{acct}.pdf\",", "            )", "            session.add(mua)", "            await session.flush()", "            mua_ids.append(mua.id)", "        await session.commit()", "", "    async with sessionmanager_datalake.session() as session:", "        found_a = await find_l3_prior_article_id(", "            session, l3_activity_id, account_id=account_a, doc_id=doc_a", "        )", "        found_b = await find_l3_prior_article_id(", "            session, l3_activity_id, account_id=account_b, doc_id=doc_b", "        )", "        assert found_a == article_ids[0]", "        assert found_b == article_ids[1]", "", "        recovered = await write_manual_upload_for_new_article(", "            session,", "            l3_activity_id,", "            \"retry content\",", "            _self_match_chunk_vectors(),", "            account_id=account_a,", "            doc_id=doc_a,", "            s3_bucket=\"test-bucket\",", "            s3_key=f\"manual_uploads/multi_anchor_{account_a}.pdf\",", "        )", "    assert recovered == (article_ids[0], manual_upload_ids[0], mua_ids[0])", "", "", "def _self_match_chunk_vectors() -> ChunkVectors:", "    \"\"\"Deterministic chunk vectors so the first attempt's stored chunks self-match on retry.", "", "    Identical embeddings across attempts give a dedup ``coverage * avg_similarity``", "    of ~1.0 against the prior article's own chunks \u2014 the exact self-match the fix", "    must exclude.", "    \"\"\"", "    return ChunkVectors(", "        chunks=[", "            ChunkEmbedding(", "                chunk_index=i,", "                chunk_text=f\"manual upload self-match chunk {i}\",", "                token_count=12,", "                embedding=[0.5] * 3072,", "            )", "            for i in range(2)", "        ]", "    )", "", "", "async def _truncate_article_graph() -> None:", "    \"\"\"Clear the article content graph so retry dedup only sees this test's rows.\"\"\"", "    async with sessionmanager_datalake.session() as session:", "        await session.execute(", "            text(\"TRUNCATE web_extraction.articles, web_extraction.duplicated_articles CASCADE\")", "        )", "        await session.commit()", "", "", "async def _prior_article_id_for_activity(l3_activity_id: UUID) -> UUID | None:", "    \"\"\"Resolve the article id written for an L3 activity via its ManualUploadAccount.\"\"\"", "    async with sessionmanager_datalake.session() as session:", "        return await session.scalar(", "            select(Tables.ManualUpload.article_id)", "            .select_from(Tables.ManualUploadAccount)", "            .join(", "                Tables.ManualUpload,", "                Tables.ManualUploadAccount.manual_upload_id == Tables.ManualUpload.id,", "            )", "            .where(Tables.ManualUploadAccount.layer_three_activity_id == l3_activity_id)", "        )", "", "", "def _build_l3_service(datalake_session, accelerate_session, client) -> WebExtractionService:", "    \"\"\"Build an L3 service with real sessions and image processing stubbed out.\"\"\"", "    service = WebExtractionService(", "        datalake_db_session=datalake_session,", "        web_extraction_client=client,", "        accelerate_db_session=accelerate_session,", "        api_helper=APIHelper(),", "    )", "    # PDF-image work needs S3 and is out of scope for the dedup/status assertions.", "    service._safe_run_layer_three_image_processing = AsyncMock()", "    return service", "", "", "@pytest.mark.asyncio", "async def test_l3_retry_after_mid_metadata_failure_completes_as_unique(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"A first upload that fails mid-metadata-LLM completes as a unique article on retry.", "", "    Drives the exact ticket window: the first attempt commits Article + chunks +", "    ManualUpload + ManualUploadAccount, then raises inside metadata enrichment", "    before any ActivityArticleStatus row is written. The retry must consult the", "    ManualUploadAccount anchor, exclude the prior article from dedup, and finish", "    as UNIQUE \u2014 not DUPLICATE-of-self. Asserts the full user-visible outcome:", "    datalake classification, accelerate Document state, and the downstream send.", "    \"\"\"", "    await _truncate_article_graph()", "    real_doc_id = await _get_real_doc_id()", "    account_id = 41_001", "", "    async with sessionmanager_datalake.session() as session:", "        await ensure_manual_upload_feed(session)", "        _, l3_activity_ids = await preseed_webex_l3_activities(db=session, num_activities=1)", "    l3_activity_id = l3_activity_ids[0]", "    s3_key = f\"manual_uploads/l3_mid_meta_{l3_activity_id}.pdf\"", "", "    # Deterministic embeddings so the prior chunks self-match on retry.", "    monkeypatch.setattr(", "        webex_module,", "        \"embed_article_chunks\",", "        AsyncMock(return_value=_self_match_chunk_vectors()),", "    )", "    monkeypatch.setattr(web_test_config, \"DEBUG\", True)", "", "    captured_sends: list[dict] = []", "", "    async def _capture_send(", "        *, client, activity_id, request_type, source_layer, destination_layer, message_payload", "    ):", "        captured_sends.append({\"request_type\": request_type, \"payload\": message_payload})", "", "    monkeypatch.setattr(webex_module, \"send_msg_to_target_queue\", _capture_send)", "", "    client = _build_webex_client_for_l3()", "", "    # --- First attempt: poison the metadata date-extraction LLM so it raises. ---", "    class _MetadataBoom(RuntimeError):", "        pass", "", "    async def _boom(**_kwargs):", "        raise _MetadataBoom(\"metadata LLM failed mid-enrichment\")", "", "    monkeypatch.setattr(webex_module, \"extract_publication_date\", _boom)", "", "    first_service = None", "    with pytest.raises(_MetadataBoom):", "        async with (", "            sessionmanager_datalake.session() as datalake_session,", "            sessionmanager_accelerate.session() as accelerate_session,", "        ):", "            first_service = _build_l3_service(datalake_session, accelerate_session, client)", "            try:", "                await first_service.manual_upload_pipeline(", "                    activity_id=l3_activity_id,", "                    account_id=account_id,", "                    doc_id=real_doc_id,", "                    s3_bucket=\"test-bucket\",", "                    s3_key=s3_key,", "                )", "            finally:", "                await first_service.api_helper.session.close()", "", "    # The failure window is exactly as the ticket describes: content committed,", "    # no ActivityArticleStatus row, no downstream send.", "    prior_article_id = await _prior_article_id_for_activity(l3_activity_id)", "    assert prior_article_id is not None, \"first attempt should have committed the Article + anchor\"", "    async with sessionmanager_datalake.session() as session:", "        sample_chunk_id = await session.scalar(", "            select(Tables.ArticleChunk)", "            .where(Tables.ArticleChunk.article_id == prior_article_id)", "            .with_only_columns(Tables.ArticleChunk.id)", "            .limit(1)", "        )", "        assert sample_chunk_id is not None, \"first attempt should have committed chunks\"", "        status_row = await find_existing_l3_outcome(session, l3_activity_id)", "    assert status_row is None, (", "        \"no ActivityArticleStatus row should exist after the mid-meta failure\"", "    )", "    assert captured_sends == [], \"no downstream message should be sent on the failed first attempt\"", "", "    # --- Retry: healthy metadata LLM boundaries. ---", "    monkeypatch.setattr(webex_module, \"extract_publication_date\", AsyncMock(return_value=None))", "    monkeypatch.setattr(", "        webex_module,", "        \"classify_article_metadata\",", "        AsyncMock(", "            return_value=ArticleClassification(", "                editorial_type=\"news_report\",", "                article_sentiment=\"neutral\",", "            )", "        ),", "    )", "", "    async with (", "        sessionmanager_datalake.session() as datalake_session,", "        sessionmanager_accelerate.session() as accelerate_session,", "    ):", "        retry_service = _build_l3_service(datalake_session, accelerate_session, client)", "        try:", "            await retry_service.manual_upload_pipeline(", "                activity_id=l3_activity_id,", "                account_id=account_id,", "                doc_id=real_doc_id,", "                s3_bucket=\"test-bucket\",", "                s3_key=s3_key,", "            )", "        finally:", "            await retry_service.api_helper.session.close()", "", "    # Datalake: completed as unique on the prior attempt's article, no duplicate.", "    async with sessionmanager_datalake.session() as session:", "        activity = await session.get(Tables.WebExtractionLayerThreeActivity, l3_activity_id)", "        assert activity is not None", "        assert activity.run_state == RunState.COMPLETED", "", "        status_rows = (", "            (", "                await session.execute(", "                    select(Tables.ActivityArticleStatus).where(", "                        Tables.ActivityArticleStatus.layer_three_activity_id == l3_activity_id", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        assert len(status_rows) == 1", "        assert status_rows[0].article_id == prior_article_id", "        assert status_rows[0].duplicated_article_id is None", "", "        dup_count = (await session.execute(select(Tables.DuplicatedArticle.id))).scalars().all()", "        assert dup_count == [], \"retry must not write a DuplicatedArticle (no self-duplicate)\"", "", "    # Accelerate: Document is not DUPLICATE and not self-linked.", "    async with sessionmanager_accelerate.session() as session:", "        document = await session.get(Document, real_doc_id)", "        assert document is not None", "        assert document.status != DocumentStatus.DUPLICATE", "        assert (document.doc_info or {}).get(\"duplicates_doc_id\") != real_doc_id", "", "    # Downstream: the ArticleTranslation message was sent exactly once.", "    assert len(captured_sends) == 1", "    assert captured_sends[0][\"request_type\"] == REQUEST_TYPES.ARTICLE_TRANSLATION_SVC", "", "", "async def _seed_l3_status_article_only() -> tuple[UUID, UUID, UUID, UUID]:", "    \"\"\"Seed an ``article_id``-only L3 status row plus a distinct duplicate outcome.", "", "    Returns ``(l3_activity_id, status_row_id, prior_article_id, duplicated_article_id)``", "    where ``duplicated_article_id`` points at a DuplicatedArticle whose matched", "    article differs from the status row's ``prior_article_id``.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        await ensure_manual_upload_feed(session)", "        _, article_ids = await preseed_article(db=session, num_articles=2)", "        prior_article_id, matched_article_id = article_ids", "        _, l3_activity_ids = await preseed_webex_l3_activities(db=session, num_activities=1)", "        l3_activity_id = l3_activity_ids[0]", "", "        status = Tables.ActivityArticleStatus(", "            article_id=prior_article_id,", "            layer_three_activity_id=l3_activity_id,", "            layer=ServiceLayer.LAYER_THREE,", "        )", "        session.add(status)", "", "        _, manual_upload_ids = await preseed_manual_upload(", "            db=session, article_ids=[matched_article_id]", "        )", "        manual_upload_account = Tables.ManualUploadAccount(", "            manual_upload_id=manual_upload_ids[0],", "            layer_three_activity_id=l3_activity_id,", "            account_id=42_777,", "            doc_id=100_001,", "            s3_bucket=\"test-bucket\",", "            s3_key=f\"manual_uploads/l3_upsert_{l3_activity_id}.pdf\",", "        )", "        session.add(manual_upload_account)", "        await session.flush()", "", "        duplicated_article = Tables.DuplicatedArticle(", "            matched_article_id=matched_article_id,", "            article_type=ArticleType.MANUAL_UPLOAD,", "            similarity_score=0.99,", "            chunk_match_info={\"matched_chunk_index\": 0, \"incoming_chunk_index\": 0},", "            content=\"later-retry duplicate content\",", "            manual_upload_account_id=manual_upload_account.id,", "        )", "        session.add(duplicated_article)", "        await session.flush()", "", "        status_row_id = status.id", "        duplicated_article_id = duplicated_article.id", "        matched = matched_article_id", "        await session.commit()", "    return l3_activity_id, status_row_id, matched, duplicated_article_id", "", "", "@pytest.mark.asyncio", "async def test_l3_status_upsert_is_last_write_wins():", "    \"\"\"A later L3 duplicate outcome overwrites an ``article_id``-only status row in place.\"\"\"", "    (", "        l3_activity_id,", "        status_row_id,", "        matched_article_id,", "        duplicated_article_id,", "    ) = await _seed_l3_status_article_only()", "", "    async with sessionmanager_datalake.session() as session:", "        service = WebExtractionService(", "            datalake_db_session=session,", "            web_extraction_client=Mock(),", "            api_helper=Mock(),", "            image_service=Mock(),", "        )", "        returned_id = await service._write_activity_article_status_record(", "            activity_id=l3_activity_id,", "            layer=ServiceLayer.LAYER_THREE,", "            article_id=matched_article_id,", "            duplicated_article_id=duplicated_article_id,", "        )", "", "    assert returned_id == status_row_id, \"L3 upsert must update the existing row in place\"", "    async with sessionmanager_datalake.session() as session:", "        rows = (", "            (", "                await session.execute(", "                    select(Tables.ActivityArticleStatus).where(", "                        Tables.ActivityArticleStatus.layer_three_activity_id == l3_activity_id", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "    assert len(rows) == 1", "    assert rows[0].id == status_row_id", "    assert rows[0].article_id == matched_article_id", "    assert rows[0].duplicated_article_id == duplicated_article_id", "", "", "async def _seed_l2_activity_status() -> tuple[UUID, UUID, UUID, UUID]:", "    \"\"\"Seed an L2 ActivityArticleStatus row.", "", "    Returns ``(l2_activity_id, status_row_id, seeded_article_id, other_article_id)``.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        feeds = await get_test_feeds(db=session, num_feeds=1)", "        feeds_sent_msgs, _ = await preseed_feeds_sent_messages(db=session, feeds=feeds)", "        _, l1_activity_ids = await preseed_webex_l1_activities(", "            db=session, feeds=feeds, feeds_sent_msgs=feeds_sent_msgs", "        )", "        _, l2_activity_ids = await preseed_webex_l2_activities(", "            db=session,", "            webex_l1_activity_id=l1_activity_ids[0],", "            sqs_msg_ids=[uuid4()],", "            num_activities=1,", "        )", "        l2_activity_id = l2_activity_ids[0]", "", "        _, article_ids = await preseed_article(db=session, num_articles=2)", "        seeded_article_id, other_article_id = article_ids", "        status = Tables.ActivityArticleStatus(", "            article_id=seeded_article_id,", "            layer_two_activity_id=l2_activity_id,", "            layer=ServiceLayer.LAYER_TWO,", "        )", "        session.add(status)", "        await session.flush()", "        status_row_id = status.id", "        await session.commit()", "    return l2_activity_id, status_row_id, seeded_article_id, other_article_id", "", "", "@pytest.mark.asyncio", "async def test_l2_status_upsert_still_no_ops_on_conflict():", "    \"\"\"L2 keeps insert-only semantics: a second write does not overwrite the row.\"\"\"", "    (", "        l2_activity_id,", "        status_row_id,", "        seeded_article_id,", "        other_article_id,", "    ) = await _seed_l2_activity_status()", "", "    async with sessionmanager_datalake.session() as session:", "        service = WebExtractionService(", "            datalake_db_session=session,", "            web_extraction_client=Mock(),", "            api_helper=Mock(),", "            image_service=Mock(),", "        )", "        returned_id = await service._write_activity_article_status_record(", "            activity_id=l2_activity_id,", "            layer=ServiceLayer.LAYER_TWO,", "            article_id=other_article_id,", "        )", "", "    assert returned_id == status_row_id", "    async with sessionmanager_datalake.session() as session:", "        row = await session.get(Tables.ActivityArticleStatus, status_row_id)", "    assert row is not None", "    assert row.article_id == seeded_article_id, \"L2 double-write must not overwrite article_id\"", "    assert row.duplicated_article_id is None", "", "", "async def _set_status_article_id(l3_activity_id: UUID, article_id: UUID) -> None:", "    \"\"\"Set ``ActivityArticleStatus.article_id`` for an activity.", "", "    ``_seed_l3_activity_with_existing_duplicate`` writes only", "    ``duplicated_article_id``; the step-0b doc_images projection keys off", "    ``article_id``, which the real pipeline sets alongside it.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        row = await session.scalar(", "            select(Tables.ActivityArticleStatus).where(", "                Tables.ActivityArticleStatus.layer_three_activity_id == l3_activity_id", "            )", "        )", "        assert row is not None", "        row.article_id = article_id", "        await session.commit()", "", "", "async def _fetch_doc_images(doc_id: int) -> list[DocImage]:", "    \"\"\"Return the doc_images rows for a document, ordered by type then source_index.\"\"\"", "    async with sessionmanager_accelerate.session() as session:", "        return list(", "            (", "                await session.execute(", "                    select(DocImage)", "                    .where(DocImage.doc_id == doc_id)", "                    .order_by(DocImage.image_type.asc(), DocImage.source_index.asc())", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "", "def _doc_image_shape(rows: list[DocImage]) -> list[tuple]:", "    \"\"\"Reduce doc_images rows to the tuple the assertions compare.", "", "    ``position`` is a Numeric column, so it comes back as ``Decimal``; floats", "    keep the comparison readable against the seeded values.", "    \"\"\"", "    return [", "        (", "            r.image_type,", "            r.s3_key,", "            r.source_index,", "            float(r.position) if r.position is not None else None,", "        )", "        for r in rows", "    ]", "", "", "async def _run_duplicate_short_circuit(", "    *, l3_activity_id: UUID, account_id: int, doc_id: int, s3_key: str", ") -> None:", "    \"\"\"Drive ``manual_upload_pipeline`` through the step-0b DUPLICATE short-circuit.\"\"\"", "    await _run_manual_upload_pipeline(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=doc_id,", "        s3_key=s3_key,", "    )", "", "", "@pytest.mark.asyncio", "async def test_l3_retry_short_circuit_projects_original_doc_images_onto_duplicate_doc(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"A same-account DUPLICATE upload ends up with the original's doc_images rows.", "", "    Two distinct accelerate documents are involved: the original (the", "    ``ManualUploadAccount.doc_id`` the linkage resolves) and the duplicate (the", "    ``doc_id`` the pipeline is driven with). Re-running the short-circuit must", "    leave the projected rows unchanged.", "    \"\"\"", "    account_id = 39_881", "    original_doc_id = await create_accelerate_document(status=DocumentStatus.READY)", "    duplicate_doc_id = await create_accelerate_document(status=DocumentStatus.PROCESSING)", "", "    l3_activity_id, _, original_article_id = await _seed_l3_activity_with_existing_duplicate(", "        account_id=account_id,", "        doc_id=original_doc_id,", "    )", "    await _set_status_article_id(l3_activity_id, original_article_id)", "    await seed_image_rows(", "        original_article_id,", "        [", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"test-bucket\",", "                s3_key=\"public/articles/2026-04-16/orig/main.png\",", "                source_index=0,", "                position=0.2,", "            ),", "            dict(", "                role=ArticleImageRole.THUMBNAIL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"test-bucket\",", "                s3_key=\"public/articles/2026-04-16/orig/thumbnail.png\",", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"test-bucket\",", "                s3_key=\"public/articles/2026-04-16/orig/supplemental-1.png\",", "                image_index=1,", "                source_index=1,", "                position=0.6,", "            ),", "        ],", "    )", "", "    def _embed_should_not_be_called(*_args, **_kwargs):", "        raise AssertionError(\"embed_article_chunks called despite short-circuit on DUPLICATE\")", "", "    monkeypatch.setattr(webex_module, \"embed_article_chunks\", _embed_should_not_be_called)", "    monkeypatch.setattr(web_test_config, \"DEBUG\", True)", "", "    s3_key = f\"manual_uploads/l3_retry_{l3_activity_id}.pdf\"", "    await _run_duplicate_short_circuit(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=duplicate_doc_id,", "        s3_key=s3_key,", "    )", "", "    expected = [", "        (ImageType.MAIN, \"public/articles/2026-04-16/orig/main.png\", 0, pytest.approx(0.2)),", "        (ImageType.THUMBNAIL, \"public/articles/2026-04-16/orig/thumbnail.png\", None, None),", "        (", "            ImageType.SUPPLEMENTAL,", "            \"public/articles/2026-04-16/orig/supplemental-1.png\",", "            1,", "            pytest.approx(0.6),", "        ),", "    ]", "    first_pass = await _fetch_doc_images(duplicate_doc_id)", "    assert sorted(_doc_image_shape(first_pass), key=lambda r: str(r[0])) == sorted(", "        expected, key=lambda r: str(r[0])", "    )", "", "    async with sessionmanager_accelerate.session() as session:", "        duplicate_document = await session.get(Document, duplicate_doc_id)", "        assert duplicate_document is not None", "        assert duplicate_document.status == DocumentStatus.DUPLICATE", "        assert (duplicate_document.doc_info or {}).get(\"duplicates_doc_id\") == original_doc_id", "", "    async with sessionmanager_datalake.session() as session:", "        activity = await session.get(Tables.WebExtractionLayerThreeActivity, l3_activity_id)", "        assert activity is not None", "        assert activity.run_state == RunState.DUPLICATE", "", "    # The original document keeps its own (empty) row set: every upsert key", "    # includes doc_id, so the projection cannot write across documents.", "    assert await _fetch_doc_images(original_doc_id) == []", "", "    # SQS redelivery re-enters the same short-circuit; the rows must not change.", "    await _run_duplicate_short_circuit(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=duplicate_doc_id,", "        s3_key=s3_key,", "    )", "    second_pass = await _fetch_doc_images(duplicate_doc_id)", "    assert _doc_image_shape(second_pass) == _doc_image_shape(first_pass)", "    assert [r.id for r in second_pass] == [r.id for r in first_pass]", "", "", "@pytest.mark.asyncio", "async def test_l3_retry_short_circuit_with_imageless_original_writes_no_doc_images(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"An original whose image work produced nothing degrades to a no-op projection.\"\"\"", "    account_id = 39_882", "    original_doc_id = await create_accelerate_document(status=DocumentStatus.READY)", "    duplicate_doc_id = await create_accelerate_document(status=DocumentStatus.PROCESSING)", "", "    l3_activity_id, _, original_article_id = await _seed_l3_activity_with_existing_duplicate(", "        account_id=account_id,", "        doc_id=original_doc_id,", "    )", "    await _set_status_article_id(l3_activity_id, original_article_id)", "    # Sentinel set, no rows: webex reached a terminal decision and produced nothing.", "    await seed_image_rows(original_article_id, [])", "", "    def _embed_should_not_be_called(*_args, **_kwargs):", "        raise AssertionError(\"embed_article_chunks called despite short-circuit on DUPLICATE\")", "", "    monkeypatch.setattr(webex_module, \"embed_article_chunks\", _embed_should_not_be_called)", "    monkeypatch.setattr(web_test_config, \"DEBUG\", True)", "", "    await _run_duplicate_short_circuit(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=duplicate_doc_id,", "        s3_key=f\"manual_uploads/l3_retry_{l3_activity_id}.pdf\",", "    )", "", "    assert await _fetch_doc_images(duplicate_doc_id) == []", "    async with sessionmanager_accelerate.session() as session:", "        duplicate_document = await session.get(Document, duplicate_doc_id)", "        assert duplicate_document is not None", "        assert duplicate_document.status == DocumentStatus.DUPLICATE", "    async with sessionmanager_datalake.session() as session:", "        activity = await session.get(Tables.WebExtractionLayerThreeActivity, l3_activity_id)", "        assert activity is not None", "        assert activity.run_state == RunState.DUPLICATE", "", "", "async def _seed_source_data(doc_id: int, rows: list[tuple[int, Any]]) -> None:", "    \"\"\"Insert ``doc.source_data`` rows for a document.", "", "    Entity classification never runs in this suite, so the original document's", "    rows -- which layer one would normally write -- are seeded directly.", "", "    :param doc_id: Document the rows belong to.", "    :type doc_id: int", "    :param rows: ``(data_model_id, data_obj)`` pairs to insert.", "    :type rows: list[tuple[int, Any]]", "    :return: None", "    :rtype: None", "    \"\"\"", "    async with sessionmanager_accelerate.session() as session:", "        for data_model_id, data_obj in rows:", "            session.add(SourceData(doc_id=doc_id, data_model_id=data_model_id, data_obj=data_obj))", "        await session.commit()", "", "", "async def _fetch_source_data(doc_id: int) -> list[SourceData]:", "    \"\"\"Return the ``source_data`` rows for a document, ordered by data model id.\"\"\"", "    async with sessionmanager_accelerate.session() as session:", "        return list(", "            (", "                await session.scalars(", "                    select(SourceData)", "                    .where(SourceData.doc_id == doc_id)", "                    .order_by(SourceData.data_model_id.asc())", "                )", "            ).all()", "        )", "", "", "def _source_data_shape(rows: list[SourceData]) -> list[tuple[int, Any]]:", "    \"\"\"Reduce ``source_data`` rows to the ``(data_model_id, data_obj)`` pairs asserted on.\"\"\"", "    return [(row.data_model_id, row.data_obj) for row in rows]", "", "", "@pytest.mark.asyncio", "async def test_l3_retry_short_circuit_projects_original_source_data_onto_duplicate_doc(", "    monkeypatch: pytest.MonkeyPatch,", "    seed_source_data_models: None,", "):", "    \"\"\"A same-account DUPLICATE upload ends up with the original's source_data rows.", "", "    The duplicate publishes no ``ArticleTranslationLayerOneMsg``, so entity", "    classification never writes its ``doc.source_data``. The projection copies the", "    original's rows under the duplicate's own ``doc_id``; re-running the", "    short-circuit must leave them, and the original's rows, unchanged.", "", "    Carries no ``ci_db`` marker, unlike the other DB-backed regression gates: the", "    ``ci_db`` job creates its accelerate database empty and ``alembic upgrade head``", "    migrates the datalake database only (``src/alembic/env.py``), so the", "    accelerate-owned ``doc`` schema this test writes does not exist there. The", "    marker would fail the job on a missing table instead of gating the projection.", "    It can be added once that schema is provisioned for the job.", "    \"\"\"", "    account_id = 39_883", "    async with sessionmanager_datalake.session() as session:", "        # A freshly migrated CI schema has no WEB_EXTRACTION_SVC request type, and", "        # every activity row's request_type_id is a NOT NULL FK to it.", "        await ensure_request_types(session)", "", "    original_doc_id = await create_accelerate_document(status=DocumentStatus.READY)", "    duplicate_doc_id = await create_accelerate_document(status=DocumentStatus.PROCESSING)", "", "    l3_activity_id, _, original_article_id = await _seed_l3_activity_with_existing_duplicate(", "        account_id=account_id,", "        doc_id=original_doc_id,", "    )", "    await _set_status_article_id(l3_activity_id, original_article_id)", "    # Sentinel set with no image rows: keeps the sibling doc_images projection a", "    # fast no-op so this test only exercises the source_data path.", "    await seed_image_rows(original_article_id, [])", "", "    seeded_source_data: list[tuple[int, Any]] = [", "        (ORG_DATA_MODEL_ID, [\"Acme Corp\", \"Globex\"]),", "        (LOC_DATA_MODEL_ID, [{\"city\": \"Boston\", \"region\": \"Northeast\", \"stateCode\": \"MA\"}]),", "        (PEOPLE_DATA_MODEL_ID, [{\"name\": \"Jane Roe\", \"evidence\": \"quoted in the release\"}]),", "    ]", "    await _seed_source_data(original_doc_id, seeded_source_data)", "", "    def _embed_should_not_be_called(*_args, **_kwargs):", "        raise AssertionError(\"embed_article_chunks called despite short-circuit on DUPLICATE\")", "", "    monkeypatch.setattr(webex_module, \"embed_article_chunks\", _embed_should_not_be_called)", "    monkeypatch.setattr(web_test_config, \"DEBUG\", True)", "", "    s3_key = f\"manual_uploads/l3_retry_{l3_activity_id}.pdf\"", "    await _run_duplicate_short_circuit(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=duplicate_doc_id,", "        s3_key=s3_key,", "    )", "", "    first_pass = await _fetch_source_data(duplicate_doc_id)", "    assert _source_data_shape(first_pass) == seeded_source_data", "", "    async with sessionmanager_accelerate.session() as session:", "        duplicate_document = await session.get(Document, duplicate_doc_id)", "        assert duplicate_document is not None", "        assert duplicate_document.status == DocumentStatus.DUPLICATE", "", "    # The original document keeps exactly its own rows: every upsert key includes", "    # doc_id, so the projection cannot write across documents.", "    assert _source_data_shape(await _fetch_source_data(original_doc_id)) == seeded_source_data", "", "    # SQS redelivery re-enters the same short-circuit; the rows must not change,", "    # and must be the same rows rather than re-inserted ones.", "    await _run_duplicate_short_circuit(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=duplicate_doc_id,", "        s3_key=s3_key,", "    )", "    second_pass = await _fetch_source_data(duplicate_doc_id)", "    assert _source_data_shape(second_pass) == _source_data_shape(first_pass)", "    assert [row.id for row in second_pass] == [row.id for row in first_pass]", "", "", "async def _seed_prior_same_account_upload(", "    *, account_id: int, original_doc_id: int", ") -> tuple[UUID, UUID]:", "    \"\"\"Preseed the state a same-account re-upload meets on its FIRST attempt.", "", "    Writes the original upload's chain -- Article -> ManualUpload ->", "    ManualUploadAccount(account_id, original_doc_id) -- plus a second, untouched", "    L3 activity for the re-upload itself. Deliberately writes no", "    ``DuplicatedArticle`` and no ``ActivityArticleStatus`` for that second", "    activity: those are what ``find_existing_l3_outcome`` looks for, and seeding", "    them is what routes a run into the step-0b short circuit instead of the", "    primary path.", "", "    :param account_id: Account that owns both the original and the re-upload.", "    :type account_id: int", "    :param original_doc_id: The original upload's accelerate document id.", "    :type original_doc_id: int", "    :return: ``(reupload_l3_activity_id, original_article_id)``.", "    :rtype: tuple[UUID, UUID]", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        await ensure_request_types(session)", "        await ensure_manual_upload_feed(session)", "        _, article_ids = await preseed_article(db=session, num_articles=1)", "        original_article_id = article_ids[0]", "        _, manual_upload_ids = await preseed_manual_upload(", "            db=session, article_ids=[original_article_id]", "        )", "        _, l3_activity_ids = await preseed_webex_l3_activities(db=session, num_activities=2)", "        original_l3_activity_id, reupload_l3_activity_id = l3_activity_ids", "", "        session.add(", "            Tables.ManualUploadAccount(", "                manual_upload_id=manual_upload_ids[0],", "                layer_three_activity_id=original_l3_activity_id,", "                account_id=account_id,", "                doc_id=original_doc_id,", "                s3_bucket=\"test-bucket\",", "                s3_key=f\"manual_uploads/l3_original_{original_l3_activity_id}.pdf\",", "            )", "        )", "        await session.commit()", "    return reupload_l3_activity_id, original_article_id", "", "", "async def _run_primary_duplicate_path(", "    monkeypatch: pytest.MonkeyPatch,", "    *,", "    l3_activity_id: UUID,", "    account_id: int,", "    doc_id: int,", "    original_article_id: UUID,", "    s3_key: str,", ") -> None:", "    \"\"\"Drive ``manual_upload_pipeline`` through the step-6 same-account DUPLICATE path.", "", "    Steps 1-3 are stubbed at the module boundary, which is the same seam the rest", "    of this suite uses: ``DEBUG`` supplies the upload text, ``embed_article_chunks``", "    would otherwise POST to the embedding service, and ``deduplicate_article``", "    would otherwise depend on a real pgvector neighbourhood. Everything from", "    step 4 on runs against the database: the ``DuplicatedArticle`` write, the", "    ``ManualUploadAccount`` lookup that selects branch ii.1, the activity-article", "    status record, and the step-6 linkage / image / source_data / status-flip", "    sequence.", "", "    :param monkeypatch: Fixture used to install the step-2 and step-3 stubs.", "    :type monkeypatch: pytest.MonkeyPatch", "    :param l3_activity_id: The re-upload's own L3 activity id.", "    :type l3_activity_id: UUID", "    :param account_id: Account performing the re-upload.", "    :type account_id: int", "    :param doc_id: The re-upload's accelerate document id.", "    :type doc_id: int", "    :param original_article_id: Article the stubbed dedup result matches.", "    :type original_article_id: UUID", "    :param s3_key: S3 key recorded on the upload rows.", "    :type s3_key: str", "    :return: None", "    :rtype: None", "    \"\"\"", "    monkeypatch.setattr(web_test_config, \"DEBUG\", True)", "", "    async def _embed(*_args: Any, **_kwargs: Any) -> ChunkVectors:", "        return _self_match_chunk_vectors()", "", "    async def _dedup(*_args: Any, **_kwargs: Any) -> DeduplicationResult:", "        return DeduplicationResult(", "            classification=DeduplicationClassification.DUPLICATE,", "            # Only article_id is read downstream; the row is never persisted.", "            best_match=Tables.ArticleChunk(article_id=original_article_id),", "            article_score=0.97,", "            match_info={\"matched_chunk_index\": 0, \"incoming_chunk_index\": 0},", "            matched_article_score=0.97,", "        )", "", "    monkeypatch.setattr(webex_module, \"embed_article_chunks\", _embed)", "    monkeypatch.setattr(webex_module, \"deduplicate_article\", _dedup)", "", "    await _run_manual_upload_pipeline(", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=doc_id,", "        s3_key=s3_key,", "    )", "", "", "@pytest.mark.asyncio", "async def test_l3_primary_duplicate_path_projects_original_source_data_onto_duplicate_doc(", "    monkeypatch: pytest.MonkeyPatch,", "    seed_source_data_models: None,", "):", "    \"\"\"The step-6 same-account DUPLICATE path persists the projected rows and flips the doc.", "", "    Companion to", "    ``test_l3_retry_short_circuit_projects_original_source_data_onto_duplicate_doc``,", "    which proves the same outcome at the step-0b short circuit. That one seeds a", "    finished duplicate outcome, so it can never reach step 6 -- the path that runs", "    on a real first-attempt re-upload. This drives the pipeline with no prior", "    outcome row, so dedup classifies DUPLICATE, branch ii.1 writes the", "    ``DuplicatedArticle``, and step 6 runs the linkage, both projections, and the", "    status flip in sequence across three accelerate commits: the image core", "    commits on entry (carrying the linkage), the source-data core commits its", "    upserts, and the caller commits the DUPLICATE flip.", "", "    Carries no ``ci_db`` marker, for the same reason as its step-0b companion: the", "    ``ci_db`` job's accelerate database has no ``doc`` schema, so the marker would", "    fail the job on a missing table instead of gating the projection.", "    \"\"\"", "    account_id = 39_885", "    original_doc_id = await create_accelerate_document(status=DocumentStatus.READY)", "    duplicate_doc_id = await create_accelerate_document(status=DocumentStatus.PROCESSING)", "", "    l3_activity_id, original_article_id = await _seed_prior_same_account_upload(", "        account_id=account_id,", "        original_doc_id=original_doc_id,", "    )", "    # Sentinel set with no image rows: keeps the sibling doc_images projection a", "    # fast no-op so this test only exercises the source_data path.", "    await seed_image_rows(original_article_id, [])", "", "    seeded_source_data: list[tuple[int, Any]] = [", "        (ORG_DATA_MODEL_ID, [\"Initech\", \"Umbrella\"]),", "        (LOC_DATA_MODEL_ID, [{\"city\": \"Austin\", \"region\": \"South\", \"stateCode\": \"TX\"}]),", "        (PEOPLE_DATA_MODEL_ID, [{\"name\": \"Sam Vale\", \"evidence\": \"named in the filing\"}]),", "    ]", "    await _seed_source_data(original_doc_id, seeded_source_data)", "", "    await _run_primary_duplicate_path(", "        monkeypatch,", "        l3_activity_id=l3_activity_id,", "        account_id=account_id,", "        doc_id=duplicate_doc_id,", "        original_article_id=original_article_id,", "        s3_key=f\"manual_uploads/l3_primary_{l3_activity_id}.pdf\",", "    )", "", "    # The projection is what this asserts; the status flip and the DuplicatedArticle", "    # row prove the run actually took step 6 rather than degrading earlier.", "    assert _source_data_shape(await _fetch_source_data(duplicate_doc_id)) == seeded_source_data", "    assert _source_data_shape(await _fetch_source_data(original_doc_id)) == seeded_source_data", "", "    async with sessionmanager_accelerate.session() as session:", "        duplicate_document = await session.get(Document, duplicate_doc_id)", "        assert duplicate_document is not None", "        assert duplicate_document.status == DocumentStatus.DUPLICATE", "        # The back-reference lives in doc_info, not in a column of its own.", "        assert (duplicate_document.doc_info or {})[\"duplicates_doc_id\"] == original_doc_id", "", "    async with sessionmanager_datalake.session() as session:", "        activity = await session.get(Tables.WebExtractionLayerThreeActivity, l3_activity_id)", "        assert activity is not None", "        assert activity.run_state == RunState.DUPLICATE", "        duplicated_article_id = await session.scalar(", "            select(Tables.ActivityArticleStatus.duplicated_article_id).where(", "                Tables.ActivityArticleStatus.layer_three_activity_id == l3_activity_id", "            )", "        )", "        assert duplicated_article_id is not None, \"step 6 runs only when ii.1 wrote the row\""], "blocks": [{"start": 1, "end": 72, "label": "Imports and module setup"}, {"start": 73, "end": 86, "label": "def _build_webex_client_for_l3"}, {"start": 87, "end": 131, "label": "def _run_manual_upload_pipeline"}, {"start": 132, "end": 152, "label": "def _seed_l3_activity_with_canonical_article"}, {"start": 153, "end": 203, "label": "def _seed_l3_activity_with_existing_duplicate"}, {"start": 204, "end": 217, "label": "def test_find_existing_l3_outcome_returns_canonical_article_row"}, {"start": 218, "end": 225, "label": "def test_find_existing_l3_outcome_returns_none_when_no_prior_attempt"}, {"start": 226, "end": 274, "label": "def test_l3_retry_short_circuits_when_prior_attempt_finished_as_duplicate"}, {"start": 275, "end": 332, "label": "def test_multi_anchor_activity_recovery_scoped_to_current_attempt"}, {"start": 333, "end": 352, "label": "def _self_match_chunk_vectors"}, {"start": 353, "end": 361, "label": "def _truncate_article_graph"}, {"start": 362, "end": 375, "label": "def _prior_article_id_for_activity"}, {"start": 376, "end": 388, "label": "def _build_l3_service"}, {"start": 389, "end": 540, "label": "def test_l3_retry_after_mid_metadata_failure_completes_as_unique"}, {"start": 541, "end": 593, "label": "def _seed_l3_status_article_only"}, {"start": 594, "end": 636, "label": "def test_l3_status_upsert_is_last_write_wins"}, {"start": 637, "end": 669, "label": "def _seed_l2_activity_status"}, {"start": 670, "end": 700, "label": "def test_l2_status_upsert_still_no_ops_on_conflict"}, {"start": 701, "end": 718, "label": "def _set_status_article_id"}, {"start": 719, "end": 734, "label": "def _fetch_doc_images"}, {"start": 735, "end": 751, "label": "def _doc_image_shape"}, {"start": 752, "end": 763, "label": "def _run_duplicate_short_circuit"}, {"start": 764, "end": 868, "label": "def test_l3_retry_short_circuit_projects_original_doc_images_onto_duplicate_doc"}, {"start": 869, "end": 909, "label": "def test_l3_retry_short_circuit_with_imageless_original_writes_no_doc_images"}, {"start": 910, "end": 928, "label": "def _seed_source_data"}, {"start": 929, "end": 942, "label": "def _fetch_source_data"}, {"start": 943, "end": 947, "label": "def _source_data_shape"}, {"start": 948, "end": 1030, "label": "def test_l3_retry_short_circuit_projects_original_source_data_onto_duplicate_doc"}, {"start": 1031, "end": 1075, "label": "def _seed_prior_same_account_upload"}, {"start": 1076, "end": 1136, "label": "def _run_primary_duplicate_path"}, {"start": 1137, "end": 1208, "label": "def test_l3_primary_duplicate_path_projects_original_source_data_onto_duplicate_doc"}], "lineCount": 1208, "sha256": "5d76ec66ce790a317fa687449826fb6a397957618426396e63e381579e21a17f", "endsWithNewline": true});
